@dataclass(frozen=True)
class OCRFixProposal:
    """A read-only, actionable proposal for one OCR quality issue."""

    sidecar_path: Path
    source_path: Path | None
    scope: OCRFixScope
    action: OCRFixAction
    summary: str
    steps: tuple[str, ...]
    reasons: tuple[str, ...]
    page_number: int | None
